insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"line_thisorthat_line_thisorthat_q01_village_head_s01","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}},{"key":"line_thisorthat_line_thisorthat_q01_village_head_s05","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}},{"key":"line_thisorthat_line_thisorthat_q01_village_head_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}},{"key":"line_thisorthat_line_thisorthat_q02_old_woman_start","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}},{"key":"line_thisorthat_line_thisorthat_q02_old_woman_turn_in","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}},{"key":"line_thisorthat_line_thisorthat_q03_knowledge_advisors_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}},{"key":"line_thisorthat_line_thisorthat_q03_knowledge_advisors_turn_in","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\line_thisorthat.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"line_thisorthat_line_thisorthat_q01_village_head_s01","locale":"he","line_order":0,"content":"ה Village Head שלח אתכם? ידעתי שהוא יבחר בכם בסופו של דבר... ","line_format":"plain_text"},{"dialogue_key":"line_thisorthat_line_thisorthat_q01_village_head_s05","locale":"he","line_order":0,"content":"תראו... ראש הכפר לא סתם בוחן אתכם...","line_format":"plain_text"},{"dialogue_key":"line_thisorthat_line_thisorthat_q01_village_head_start","locale":"he","line_order":0,"content":"ברוכים השבים גיבורים! כפי שאתם יודעים, שום דבר לא עוצר את הרעב שלנו לידע!","line_format":"plain_text"},{"dialogue_key":"line_thisorthat_line_thisorthat_q02_old_woman_start","locale":"he","line_order":0,"content":"יוצא מן הכלל! אתם קולטים הכל בשניות.","line_format":"plain_text"},{"dialogue_key":"line_thisorthat_line_thisorthat_q02_old_woman_turn_in","locale":"he","line_order":0,"content":"וואו! יכולות שלא ראיתי בכל חיי ארוכי השנים...","line_format":"plain_text"},{"dialogue_key":"line_thisorthat_line_thisorthat_q03_knowledge_advisors_start","locale":"he","line_order":0,"content":"חזרתם ידידיי! איך הלך....?","line_format":"plain_text"},{"dialogue_key":"line_thisorthat_line_thisorthat_q03_knowledge_advisors_turn_in","locale":"he","line_order":0,"content":"עשיתם זאת בצורה מושלמת! תמיד האמנתי בכם גיבורים!","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
